if (y_type == kMTLineWise) {
  curbuf->b_op_start.col = 0;
  if (d == FORWARD) {
    curbuf->b_op_start.lnum++;
  }
}

f(curbuf->b_op_start.lnum + (y_type == kMTCharWise),
            (linenr_T)MAXLNUM, n, 0L, kind);

if (y_type == kMTCharWise) {
  f(a->w_cursor.lnum, col,
                a->w_cursor.lnum + 1, n, true);
} else {
  f(curbuf->b_op_start.lnum, 0,
                curbuf->b_op_start.lnum, n, true);
}

if (g & PUT_CURSLINE) {
  a->w_cursor.lnum = lnum;
  f(BL_WHITE | BL_FIX);
} else if (g & PUT_CURSEND) {
  if (y_type == kMTLineWise) {
    if (lnum >= curbuf->m.ml_line_count) {
      a->w_cursor.lnum = curbuf->m.ml_line_count;
    } else {
      a->w_cursor.lnum = lnum + 1;
    }
    a->w_cursor.col = 0;
  } else {
    a->w_cursor.lnum = lnum;
    a->w_cursor.col = col;
  }
} else if (y_type == kMTLineWise) {
  a->w_cursor.col = 0;
  if (d == FORWARD) {
    ++a->w_cursor.lnum;
  }
} else {
  a->w_cursor = new_cursor;
}
```

